const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  const brooklyn = ee.Geometry.Polygon(
    [[-74.04, 40.57],
      [-73.85, 40.57],
      [-73.85, 40.73],
      [-74.04, 40.73],
      [-74.04, 40.57]]
  );

  const startDay = '10-01';
  const endDay = '10-23';
  const bandName = 'tropospheric_NO2_column_number_density'; // Unit: mol/m^2

  const processYear = async (year, geometry) => {
    const startDate = ee.Date(`${year}-${startDay}`);
    const endDate = ee.Date(`${year}-${endDay}`);

    let collection = ee.ImageCollection('COPERNICUS/S5P/OFFL/L3_NO2')
      .filterBounds(geometry)
      .filterDate(startDate, endDate)
      .select([bandName, 'qa_value', 'cloud_fraction']);

    const initialSize = collection.size().getInfo();
    if (initialSize === 0) {
      return { meanNO2: null, imageCount: 0, validPixels: 0, message: `No images found for ${year}.` };
    }

    // Apply quality and cloud mask
    collection = collection
      .filter(ee.Filter.gt('qa_value', 0.75)) // QA value for good quality data
      .filter(ee.Filter.lt('cloud_fraction', 0.2)); // Filter out images with high cloud fraction

    const postFilterSize = collection.size().getInfo();
    if (postFilterSize === 0) {
      return { meanNO2: null, imageCount: 0, validPixels: 0, message: `No images found after QA/Cloud filter for ${year}.` };
    }

    // Calculate the mean image for the period
    const meanImage = collection.mean();

    // Calculate valid pixels and mean NO2 concentration
    const reducer = ee.Reducer.mean().combine({
      reducer2: ee.Reducer.count(),
      sharedInputs: true
    });

    const stats = meanImage.reduceRegion({
      reducer: reducer,
      geometry: geometry,
      scale: 1113.2, // ~1km resolution for S5P
      maxPixels: 1e9
    }).getInfo();

    const meanNO2 = stats ? stats[bandName] : null;
    const validPixels = stats ? stats[`${bandName}_count`] : 0;

    if (validPixels === 0) {
      return { meanNO2: null, imageCount: postFilterSize, validPixels: 0, message: `No valid pixels after masking for ${year}.` };
    }

    return { meanNO2: meanNO2, imageCount: postFilterSize, validPixels: validPixels };
  };

  const results2021 = await processYear(2021, brooklyn);
  const results2019 = await processYear(2019, brooklyn);
  const results2018 = await processYear(2018, brooklyn);

  console.log(`2021: Images: ${results2021.imageCount}, Pixels: ${results2021.validPixels}, NO2: ${results2021.meanNO2 !== null ? results2021.meanNO2.toExponential(2) : 'N/A'}`);
  console.log(`2019: Images: ${results2019.imageCount}, Pixels: ${results2019.validPixels}, NO2: ${results2019.meanNO2 !== null ? results2019.meanNO2.toExponential(2) : 'N/A'}`);
  console.log(`2018: Images: ${results2018.imageCount}, Pixels: ${results2018.validPixels}, NO2: ${results2018.meanNO2 !== null ? results2018.meanNO2.toExponential(2) : 'N/A'}`);

  // Check for C1 (Empty Collection)
  if (results2021.imageCount === 0 || results2019.imageCount === 0 || results2018.imageCount === 0) {
    if (results2021.message) console.log(results2021.message);
    if (results2019.message) console.log(results2019.message);
    if (results2018.message) console.log(results2018.message);
    console.log("C1");
    return;
  }

  // Check for C2 (No Valid Pixels)
  if (results2021.validPixels === 0 || results2019.validPixels === 0 || results2018.validPixels === 0) {
    if (results2021.message) console.log(results2021.message);
    if (results2019.message) console.log(results2019.message);
    if (results2018.message) console.log(results2018.message);
    console.log("C2");
    return;
  }

  // Check for C3 (Calculation Failure - None, NaN)
  if (results2021.meanNO2 === null || isNaN(results2021.meanNO2) ||
      results2019.meanNO2 === null || isNaN(results2019.meanNO2) ||
      results2018.meanNO2 === null || isNaN(results2018.meanNO2)) {
    console.log("C3");
    return;
  }

  // Compare 2021 to 2019 and 2018
  const isLowerThan2019 = results2021.meanNO2 < results2019.meanNO2;
  const isLowerThan2018 = results2021.meanNO2 < results2018.meanNO2;

  if (isLowerThan2019 && isLowerThan2018) {
    console.log("A"); // Yes
  } else {
    console.log("B"); // No
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
